/* Deterministic code generator demo; actual generation runs only in local loopback Mock Server. */
(function(){'use strict';
const SAMPLE={entityName:'AssetTag',packageName:'com.peachsoft.media',tableName:'media_asset_tag',description:'数字资产标签',fields:[{name:'assetId',type:'Long',required:true},{name:'tagName',type:'String',length:128,required:true},{name:'sortOrder',type:'Integer',required:false},{name:'enabled',type:'Boolean',required:true}]};
const T=['String','Long','Integer','Boolean','BigDecimal','LocalDateTime'];
let fields=SAMPLE.fields.map(x=>({...x})),result=null,selected=0,pending=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){const target=document.getElementById('codegen-toast');target.textContent=message;target.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>target.classList.remove('visible'),2800);}
function formFields(){return fields.map((f,i)=>`<div class="codegen-field" data-row="${i}"><input data-kind="name" aria-label="字段 ${i+1} 名称" value="${esc(f.name)}" placeholder="fieldName" maxlength="40"><select data-kind="type" aria-label="字段 ${i+1} 类型">${T.map(t=>`<option ${t===f.type?'selected':''}>${t}</option>`).join('')}</select><label><input data-kind="required" type="checkbox" ${f.required?'checked':''}>必填</label><button class="remove" type="button" data-remove="${i}" aria-label="删除字段 ${i+1}">×</button></div>`).join('');}
function render(){document.getElementById('codegen-root').innerHTML=`<div class="codegen-shell"><aside class="codegen-sidebar"><a class="brand" href="../index.html">◉ Peach Media<span>DEVELOPER WORKSPACE</span></a><nav aria-label="开发者导航"><a href="./index.html">◈ 开发者平台</a><a href="./index.html#projects">▣ 应用项目</a><a href="./index.html#credentials">⌘ API 凭证</a><a class="active" href="./codegen.html" aria-current="page">⚙ 智能代码生成</a><a href="../openapi/index.html">↗ Open API</a></nav><div class="codegen-side-note">CODEGEN LAB / 0.1<br>以结构化业务模型生成可审查的代码骨架。<br>Agent 与 MCP 为后续扩展。</div></aside><main class="codegen-main" id="codegen-main"><div class="codegen-breadcrumb"><a href="./index.html">开发者平台</a> / 智能代码生成</div><header class="codegen-header"><div><h1>智能代码生成</h1><p>从一份实体设计出发，生成后端、SQL、权限、API 契约和 HTML 页面。生成内容可逐文件审查，不会自动提交仓库。</p></div><span class="pill blue">PREVIEW · TEMPLATE ENGINE</span></header><div class="codegen-hero"><div><span class="eyebrow">FROM SCHEMA TO REVIEWABLE CODE</span><strong>一个业务实体，生成一套一致的工程骨架。</strong><p>第一阶段使用确定性模板，不调用大模型；后续让 Agent Skill 将自然语言转为结构化 Schema。</p></div><div class="glyph">{ }</div></div><p class="codegen-warning">演示环境提醒：请运行 <code>node prototype/mock-server.cjs</code>。生成结果不包含真实权限实现或完整 Service 实现，须通过人工审查和后端编译验收后才能使用。</p><div class="codegen-layout"><section class="codegen-card"><div class="codegen-card-header"><h2>01 · 业务实体定义</h2><span>结构化输入</span></div><div class="codegen-card-body"><form id="codegen-form" class="codegen-form" novalidate><div class="codegen-form-grid"><label>实体名（PascalCase）<input name="entityName" required maxlength="50" value="${esc(SAMPLE.entityName)}"></label><label>数据库表名<input name="tableName" required maxlength="63" value="${esc(SAMPLE.tableName)}"></label><label style="grid-column:1/-1">Java 包名<input name="packageName" required maxlength="120" value="${esc(SAMPLE.packageName)}"></label><label style="grid-column:1/-1">业务描述<input name="description" required maxlength="100" value="${esc(SAMPLE.description)}"></label></div><div class="codegen-fields"><div class="codegen-fields-head"><span>字段配置（公共字段自动补齐）</span><button class="codegen-button" id="add-field" type="button">＋ 添加字段</button></div><div id="field-list">${formFields()}</div><p class="codegen-hint">默认补齐 id、tenantId、projectId、createdAt、updatedAt。字段支持 String / Long / Integer / Boolean / BigDecimal / LocalDateTime；新增字段不自动获得访问权限。</p></div><div class="codegen-form-actions"><button class="codegen-button primary" id="generate" type="submit">生成并预览代码</button><button class="codegen-button" id="download" type="button" disabled>下载 ZIP</button><button class="codegen-button" id="reset" type="button">恢复样例</button></div><div id="codegen-status" class="codegen-status" role="status" aria-live="polite">启动本地 Mock 服务后点击“生成并预览代码”。</div></form></div></section><section class="codegen-card"><div class="codegen-card-header"><h2>02 · 产物审查</h2><span id="file-count">尚未生成</span></div><div class="codegen-files"><div id="file-list" class="codegen-file-list"><div class="codegen-empty">生成后展示文件目录</div></div><div class="codegen-preview"><div class="codegen-preview-tools"><span id="file-title">未选择文件</span><button class="codegen-button" id="copy-file" type="button" disabled>复制代码</button></div><pre id="file-code"><code>等待生成...</code></pre></div></div></section></div></main></div>`;
  bind();previewFile();}
function bind(){const form=document.getElementById('codegen-form');
  form.addEventListener('submit',async event=>{event.preventDefault();await preview();});
  document.getElementById('add-field').addEventListener('click',()=>{if(fields.length>=24)return notify('最多支持 24 个业务字段');fields.push({name:'newField'+(fields.length+1),type:'String',required:false});redrawFields();markStale();});
  document.getElementById('field-list').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;if(fields.length<=1)return notify('至少保留一个字段');fields.splice(Number(b.dataset.remove),1);redrawFields();markStale();});
  document.getElementById('field-list').addEventListener('input',onFieldChange);
  document.getElementById('field-list').addEventListener('change',onFieldChange);
  form.querySelectorAll('.codegen-form-grid input').forEach(el=>el.addEventListener('input',markStale));
  document.getElementById('reset').addEventListener('click',()=>{fields=SAMPLE.fields.map(x=>({...x}));result=null;selected=0;render();notify('已恢复资产标签示例');});
  document.getElementById('download').addEventListener('click',download);
  document.getElementById('copy-file').addEventListener('click',async()=>{if(!result)return;try{await navigator.clipboard.writeText(result.files[selected].content);notify('当前文件代码已复制');}catch{notify('浏览器禁止复制，请选中文本手动复制');}});
  document.getElementById('file-list').addEventListener('click',e=>{const el=e.target.closest('button[data-file]');if(!el)return;selected=Number(el.dataset.file);previewFile();});
}
function redrawFields(){document.getElementById('field-list').innerHTML=formFields();}
function onFieldChange(e){const field=e.target.closest('[data-row]');if(!field)return;const index=Number(field.dataset.row),kind=e.target.dataset.kind;if(!kind)return;fields[index][kind]=kind==='required'?e.target.checked:e.target.value;markStale();}
function markStale(){if(!result)return;result=null;selected=0;previewFile();document.getElementById('file-count').textContent='配置已更改，需重新生成';document.getElementById('download').disabled=true;document.getElementById('codegen-status').textContent='配置已更改，请重新生成。';}
function schema(){const form=document.getElementById('codegen-form');const value=n=>form.elements.namedItem(n).value.trim();return {entityName:value('entityName'),tableName:value('tableName'),packageName:value('packageName'),description:value('description'),fields:fields.map(f=>({name:f.name.trim(),type:f.type,required:f.required,...(f.type==='String'?{length:f.length||255}:{})}))};}
async function call(endpoint){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('/demo/v1/codegen/'+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({schema:schema()}),signal:controller.signal});if(endpoint==='export'&&response.ok)return response.blob();const payload=await response.json();if(!response.ok)throw Error(payload.message||'生成失败');return payload.data;}finally{clearTimeout(timer);}}
async function preview(){if(pending)return;pending=true;document.getElementById('generate').disabled=true;const info=document.getElementById('codegen-status');info.classList.remove('error');info.textContent='正在校验输入并生成代码骨架…';try{result=await call('preview');selected=0;document.getElementById('file-count').textContent=`${result.files.length} 个可审查文件`;document.getElementById('download').disabled=false;info.textContent='生成完成（模板预览），已输出 '+result.files.length+' 个文件；请审查后再导出。';previewFile();}catch(error){result=null;selected=0;previewFile();info.classList.add('error');info.textContent=error.name==='AbortError'?'请求超时，请检查本地服务。':error.message==='Failed to fetch'?'本地 Mock API 未启动。请执行 node prototype/mock-server.cjs。':'生成失败：'+error.message;}finally{pending=false;document.getElementById('generate').disabled=false;}}
function previewFile(){const list=document.getElementById('file-list'),title=document.getElementById('file-title'),code=document.getElementById('file-code');if(!result){list.innerHTML='<div class="codegen-empty">生成后展示文件目录</div>';title.textContent='未选择文件';code.textContent='等待生成...';const copy=document.getElementById('copy-file');if(copy)copy.disabled=true;return;}list.innerHTML=result.files.map((f,i)=>`<button type="button" data-file="${i}" class="${i===selected?'active':''}" title="${esc(f.path)}">${esc(f.path.split('/').pop())}</button>`).join('');title.textContent=result.files[selected].path;code.textContent=result.files[selected].content;document.getElementById('copy-file').disabled=false;}
async function download(){if(!result||pending)return;pending=true;const btn=document.getElementById('download');btn.disabled=true;const info=document.getElementById('codegen-status');try{const blob=await call('export'),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='peach-codegen-'+result.normalizedSchema.slug+'.zip';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('代码骨架 ZIP 已生成');}catch(error){info.classList.add('error');info.textContent='导出失败：'+error.message;}finally{pending=false;btn.disabled=!result;}}
render();
})();
